\set ON_ERROR_STOP on
begin;
do $$declare a uuid:='00000000-0000-4000-8000-000000000001';b uuid:='00000000-0000-4000-8000-000000000002';outsider uuid:='00000000-0000-4000-8000-000000000004';t uuid:='10000000-0000-4000-8000-000000000001';bank uuid;job uuid;second_job uuid;data jsonb;receipt jsonb;ticket jsonb;scan_token uuid;parse_token uuid;view jsonb;scan jsonb;parsed jsonb;ack jsonb;adopted jsonb;imp uuid;row jsonb;rev integer;
begin
 bank:=(assessment_command(a,t,'qti-bank-001','bank.create','{"title":"QTI transaction test"}')->>'id')::uuid;
 data:=jsonb_build_object('bank_id',bank,'filename','questions.zip','source_hash',repeat('a',64),'processor_id',repeat('f',64),'byte_length',22,'parts',jsonb_build_array(jsonb_build_object('sha256',repeat('a',64),'byte_length',22)));
 receipt:=assessment_qti_command(a,t,'qti-source-begin','source.begin',data);job:=(receipt->>'id')::uuid;
 if assessment_qti_command(a,t,'qti-source-begin','source.begin',data)<>receipt or assessment_qti_command(a,t,'qti-source-duplicate','source.begin',data)->>'id'<>job::text then raise exception 'QTI source duplicated or lost receipt';end if;
 begin perform assessment_qti_command(b,t,'qti-source-other','source.begin',data);raise exception 'Source silently taken over';exception when insufficient_privilege then null;end;
 begin perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',job));raise exception 'Incomplete source queued';exception when check_violation then null;end;
 begin perform assessment_qti_transport(b,t,'part.authorize',jsonb_build_object('job_id',job,'index',0));raise exception 'Other author granted upload';exception when insufficient_privilege then null;end;
 begin perform assessment_qti_read(outsider,t,job,0,50);raise exception 'Foreign actor saw private source';exception when insufficient_privilege then null;end;
 if assessment_qti_claim('parse',repeat('f',64),1)<>'[]' then raise exception 'Parser claimed unscanned source';end if;
 data:=jsonb_build_object('job_id',job,'index',0,'sha256',repeat('a',64),'byte_length',22,'cipher_sha256',repeat('b',64),'iv',repeat('c',24),'key_id','fixture-key','etag','etag-one','object_key','assessment-qti/'||t||'/'||job||'/0/'||repeat('a',64));
 begin perform assessment_qti_transport(a,t,'part.receipt',data||jsonb_build_object('object_key','assessment/'||t||'/'||job));raise exception 'Prompt-media path entered QTI source';exception when unique_violation then null;end;
 receipt:=assessment_qti_transport(a,t,'part.receipt',data);
 if assessment_qti_transport(a,t,'part.receipt',data)<>receipt then raise exception 'Part receipt replay changed';end if;
 begin perform assessment_qti_transport(a,t,'part.receipt',data||'{"etag":"changed"}');raise exception 'Part envelope overwritten';exception when unique_violation then null;end;
 perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',job));perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',job));
 if(select count(*) from assessment_audit_events where target_id=job and action='qti.source.completed')<>1 then raise exception 'Completion replay duplicated audit';end if;
 if assessment_qti_claim('scan',repeat('e',64),1)<>'[]' then raise exception 'Different processor claimed source';end if;
 ticket:=assessment_qti_claim('scan',repeat('f',64),1)->0;scan_token:=(ticket->>'lease_token')::uuid;
 if ticket->>'id'<>job::text or assessment_qti_claim('scan',repeat('f',64),1)<>'[]' then raise exception 'Scan claim lost scope/exclusivity';end if;
 begin perform assessment_qti_bundle(job,'scan',scan_token,repeat('e',64),false);raise exception 'Wrong parser release received source';exception when unique_violation then null;end;
 view:=assessment_qti_bundle(job,'scan',scan_token,repeat('f',64),true);if view->>'source_hash'<>repeat('a',64) or jsonb_array_length(view->'parts')<>1 then raise exception 'Source bundle changed';end if;
 scan:=jsonb_build_object('source_hash',repeat('a',64),'byte_length',22,'verdict','clean','engine_version','SQL fixture only - not actual AV','signature_version',repeat('d',64),'report_hash',repeat('e',64),'scanner_id','fixture-scanner');
 begin perform assessment_qti_report(job,'scan',scan_token,repeat('f',64),scan||jsonb_build_object('source_hash',repeat('b',64)));raise exception 'Changed source scanned';exception when unique_violation then null;end;
 ack:=assessment_qti_report(job,'scan',scan_token,repeat('f',64),scan);if assessment_qti_report(job,'scan',scan_token,repeat('f',64),scan)<>ack then raise exception 'Scan lost-reply receipt changed';end if;
 if assessment_qti_bundle(job,'scan',scan_token,repeat('f',64),false)->>'done'<>'true' then raise exception 'Committed scan not recoverable';end if;
 begin perform assessment_qti_report(job,'scan',scan_token,repeat('f',64),scan||'{"verdict":"rejected"}');raise exception 'Committed scan overwritten';exception when unique_violation then null;end;
 ticket:=assessment_qti_claim('parse',repeat('f',64),1)->0;parse_token:=(ticket->>'lease_token')::uuid;
 row:=jsonb_build_object('line',1,'source_path','items/a.xml','identifier','A','item',jsonb_build_object('schema_version','assessment.item.v1','type','single_choice','locale','en','prompt','Which option?','options',jsonb_build_array(jsonb_build_object('id','A','text','One'),jsonb_build_object('id','B','text','Two')),'max_score',1,'tags','[]'::jsonb),'key',jsonb_build_object('correct','A','case_sensitive',true,'partial_credit',false),'fingerprint',repeat('b',64),'warnings',jsonb_build_array('Independent content/key/license approval remains required.'));
 parsed:=jsonb_build_object('schema_version','assessment.qti-normalized.v1','source_hash',repeat('a',64),'parser_review_hash',repeat('c',64),'rows',jsonb_build_array(row),'blocked','[]'::jsonb);
 begin perform assessment_qti_report(job,'parse',scan_token,repeat('f',64),parsed);raise exception 'Scanner lease wrote parser result';exception when unique_violation then null;end;
 ack:=assessment_qti_report(job,'parse',parse_token,repeat('f',64),parsed);if assessment_qti_report(job,'parse',parse_token,repeat('f',64),parsed)<>ack then raise exception 'Parser lost-reply receipt changed';end if;
 view:=assessment_qti_read(a,t,job,0,50);rev:=(view->>'revision')::integer;
 if view ? 'lease_token' or view ? 'lease_until' or jsonb_array_length(view->'rows')<>1 or view->>'state'<>'review_ready' then raise exception 'Private review projection invalid';end if;
 if(select count(*) from assessment_items where bank_id=bank)<>0 then raise exception 'Parser created items before human review';end if;
 begin perform assessment_qti_command(a,t,'qti-unacknowledged','adopt',jsonb_build_object('id',job,'expected_revision',rev,'review_hash',view->>'review_hash','acknowledged',false,'reason','Review'));raise exception 'Unacknowledged proposal adopted';exception when unique_violation then null;end;
 data:=jsonb_build_object('id',job,'expected_revision',rev,'review_hash',view->>'review_hash','acknowledged',true,'reason','Reviewed source provenance, licensing, diagnostics and proposed questions.');
 adopted:=assessment_qti_command(a,t,'qti-adopt-001','adopt',data);imp:=(adopted->'import'->>'id')::uuid;
 if assessment_qti_command(a,t,'qti-adopt-001','adopt',data)<>adopted then raise exception 'Adoption duplicated after lost reply';end if;
 if(select raw_source_hash from assessment_qti_adoptions where job_id=job)<>repeat('a',64) or (select format from assessment_bank_imports where id=imp)<>'qti3' then raise exception 'QTI provenance lost';end if;
 if(select source_hash from assessment_bank_imports where id=imp)<>view->>'review_hash' then raise exception 'Normalized snapshot identity lost';end if;
 perform assessment_bank_import_command(a,t,'qti-bank-confirm','confirm',jsonb_build_object('id',imp,'expected_revision',1,'review_hash',adopted->'import'->>'review_hash','reason','Reviewed exact imported bank rows'));
 perform assessment_bank_import_command(a,t,'qti-bank-step','step',jsonb_build_object('id',imp,'expected_revision',2));
 if(select count(*) from assessment_item_versions v join assessment_items i on i.id=v.item_id where i.bank_id=bank and v.status='draft' and v.approved_by is null)<>1 then raise exception 'QTI draft creation bypassed or lost approval boundary';end if;
 update tenant_memberships set status='inactive' where tenant_id=t and user_id=a;
 begin perform assessment_qti_command(a,t,'qti-adopt-001','adopt',data);raise exception 'Revoked actor replayed adoption';exception when insufficient_privilege then null;end;
 begin perform assessment_qti_read(a,t,job,0,50);raise exception 'Revoked actor read cached keys';exception when insufficient_privilege then null;end;
 update tenant_memberships set status='active' where tenant_id=t and user_id=a;
 -- New source: an expired scan lease must be replaced, not extended by replay.
 data:=jsonb_build_object('bank_id',bank,'filename','cancel.zip','source_hash',repeat('b',64),'processor_id',repeat('f',64),'byte_length',22,'parts',jsonb_build_array(jsonb_build_object('sha256',repeat('b',64),'byte_length',22)));
 second_job:=(assessment_qti_command(a,t,'qti-second-source','source.begin',data)->>'id')::uuid;
 perform assessment_qti_transport(a,t,'part.receipt',jsonb_build_object('job_id',second_job,'index',0,'sha256',repeat('b',64),'byte_length',22,'cipher_sha256',repeat('b',64),'iv',repeat('d',24),'key_id','fixture-key','etag','etag-two','object_key','assessment-qti/'||t||'/'||second_job||'/0/'||repeat('b',64)));
 perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',second_job));scan_token:=(assessment_qti_claim('scan',repeat('f',64),1)->0->>'lease_token')::uuid;
 update assessment_qti_jobs set lease_until=clock_timestamp()-interval '1 second',revision=revision+1 where id=second_job;
 ticket:=assessment_qti_claim('scan',repeat('f',64),1)->0;
 begin perform assessment_qti_report(second_job,'scan',scan_token,repeat('f',64),scan||jsonb_build_object('source_hash',repeat('b',64)));raise exception 'Expired replaced lease reported';exception when unique_violation then null;end;
 rev:=(assessment_qti_read(b,t,second_job,0,50)->>'revision')::integer;
 perform assessment_qti_command(b,t,'qti-cancel-running','cancel',jsonb_build_object('id',second_job,'expected_revision',rev,'reason','Stop this exact in-flight source.'));
 begin perform assessment_qti_bundle(second_job,'scan',(ticket->>'lease_token')::uuid,repeat('f',64),false);raise exception 'Cancelled job supplied bytes';exception when insufficient_privilege then null;end;
 begin perform assessment_qti_report(second_job,'scan',(ticket->>'lease_token')::uuid,repeat('f',64),scan||jsonb_build_object('source_hash',repeat('b',64)));raise exception 'Cancelled job accepted result';exception when insufficient_privilege then null;end;
 if (assessment_qti_command(b,t,'qti-replacement-upload','source.begin',data)->>'id')::uuid=second_job then raise exception 'Cancelled source prevented a fresh owner upload';end if;
 begin update assessment_qti_reports set payload='{}' where job_id=job;raise exception 'Parser history mutable';exception when check_violation then null;end;
 if has_function_privilege('authenticated','assessment_qti_report(uuid,text,uuid,text,jsonb)','execute') or has_function_privilege('authenticated','assessment_qti_claim(text,text,integer)','execute') or has_table_privilege('authenticated','assessment_qti_reports','select') then raise exception 'QTI private authority leaked';end if;
end;$$;
do $$declare a uuid:='00000000-0000-4000-8000-000000000001';t uuid:='10000000-0000-4000-8000-000000000001';bank uuid;job uuid;ticket jsonb;source text;scan jsonb;parsed jsonb;view jsonb;n integer;
begin
 bank:=(assessment_command(a,t,'qti-negative-bank','bank.create','{"title":"QTI blocked source checks"}')->>'id')::uuid;
 for n in 1..2 loop
  source:=repeat(case n when 1 then 'c' else 'd' end,64);
  job:=(assessment_qti_command(a,t,'qti-negative-source-'||n,'source.begin',jsonb_build_object('bank_id',bank,'filename','blocked.zip','source_hash',source,'processor_id',repeat('e',64),'byte_length',22,'parts',jsonb_build_array(jsonb_build_object('sha256',source,'byte_length',22))))->>'id')::uuid;
  perform assessment_qti_transport(a,t,'part.receipt',jsonb_build_object('job_id',job,'index',0,'sha256',source,'byte_length',22,'cipher_sha256',repeat('b',64),'iv',repeat('c',24),'key_id','fixture-key','etag','negative-'||n,'object_key','assessment-qti/'||t||'/'||job||'/0/'||source));perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',job));
  ticket:=assessment_qti_claim('scan',repeat('e',64),1)->0;
  scan:=jsonb_build_object('source_hash',source,'byte_length',22,'verdict',case n when 1 then 'rejected' else 'clean' end,'engine_version','SQL fixture only','signature_version',repeat('a',64),'report_hash',repeat('b',64));
  perform assessment_qti_report(job,'scan',(ticket->>'lease_token')::uuid,repeat('e',64),scan);
  if n=1 then
   if assessment_qti_claim('parse',repeat('e',64),1)<>'[]' then raise exception 'Rejected source entered parser queue';end if;
  else
   ticket:=assessment_qti_claim('parse',repeat('e',64),1)->0;
   parsed:=jsonb_build_object('schema_version','assessment.qti-normalized.v1','source_hash',source,'parser_review_hash',repeat('f',64),'rows','[]'::jsonb,'blocked',jsonb_build_array(jsonb_build_object('path','items/custom.xml','code','custom_scoring','message','Explicit mapping remains required.')));
   perform assessment_qti_report(job,'parse',(ticket->>'lease_token')::uuid,repeat('e',64),parsed);
  end if;
  view:=assessment_qti_read(a,t,job,0,50);if view->>'state'<>'blocked' then raise exception 'Unsafe/unsupported source was not blocked';end if;
  begin perform assessment_qti_command(a,t,'qti-negative-adopt-'||n,'adopt',jsonb_build_object('id',job,'expected_revision',view->'revision','review_hash',coalesce(view->>'review_hash',repeat('a',64)),'acknowledged',true,'reason','Must not bypass rejection.'));raise exception 'Blocked source adopted';exception when check_violation then null;end;
  begin perform assessment_qti_command(a,t,'qti-negative-retry-'||n,'retry',jsonb_build_object('id',job,'expected_revision',view->'revision','reason','Must not erase a committed rejection/mapping review.'));raise exception 'Immutable rejection silently reprocessed';exception when check_violation then null;end;
 end loop;
 if exists(select 1 from assessment_items where bank_id=bank) then raise exception 'Blocked sources created questions';end if;
end;$$;
do $$declare a uuid:='00000000-0000-4000-8000-000000000001';b uuid:='00000000-0000-4000-8000-000000000002';t uuid:='10000000-0000-4000-8000-000000000001';bank uuid;job uuid;ticket jsonb;old_token uuid;view jsonb;
begin
 bank:=(assessment_command(a,t,'qti-recovery-bank','bank.create','{"title":"QTI processing recovery"}')->>'id')::uuid;
 job:=(assessment_qti_command(a,t,'qti-recovery-source','source.begin',jsonb_build_object('bank_id',bank,'filename','recovery.zip','source_hash',repeat('a',64),'processor_id',repeat('d',64),'byte_length',22,'parts',jsonb_build_array(jsonb_build_object('sha256',repeat('a',64),'byte_length',22))))->>'id')::uuid;
 perform assessment_qti_transport(a,t,'part.receipt',jsonb_build_object('job_id',job,'index',0,'sha256',repeat('a',64),'byte_length',22,'cipher_sha256',repeat('b',64),'iv',repeat('c',24),'key_id','fixture-key','etag','recovery','object_key','assessment-qti/'||t||'/'||job||'/0/'||repeat('a',64)));perform assessment_qti_transport(a,t,'complete',jsonb_build_object('job_id',job));
 ticket:=assessment_qti_claim('scan',repeat('d',64),1)->0;old_token:=(ticket->>'lease_token')::uuid;
 update tenant_memberships set status='inactive' where tenant_id=t and user_id=a;
 begin perform assessment_qti_bundle(job,'scan',old_token,repeat('d',64),false);raise exception 'Revoked processing owner supplied source';exception when insufficient_privilege then null;end;
 view:=assessment_qti_read(b,t,job,0,50);
 perform assessment_qti_command(b,t,'qti-explicit-recovery','retry',jsonb_build_object('id',job,'expected_revision',view->'revision','reason','Current editor explicitly assumes unfinished processing.'));
 if(select processing_actor from assessment_qti_jobs where id=job)<>b then raise exception 'Recovery silently retained revoked actor';end if;
 ticket:=assessment_qti_claim('scan',repeat('d',64),1)->0;if ticket is null or ticket->>'lease_token'=old_token::text then raise exception 'Recovery did not issue a fresh fenced lease';end if;
 begin perform assessment_qti_bundle(job,'scan',old_token,repeat('d',64),false);raise exception 'Old processing owner lease survived recovery';exception when unique_violation then null;end;
 update assessment_qti_jobs set attempts=10,lease_until=clock_timestamp()-interval '1 second',revision=revision+1 where id=job;
 ticket:=assessment_qti_claim('scan',repeat('d',64),1);
 if ticket<>'[]' then raise exception 'Attempt exhaustion issued another unattended lease';end if;
 if(select state from assessment_qti_jobs where id=job)<>'blocked' then raise exception 'Attempt exhaustion did not block unattended processing';end if;
 if(select count(*) from assessment_audit_events where target_id=job and action='qti.processing.exhausted' and actor_kind='system')<>1 then raise exception 'Exhaustion lacked system audit';end if;
 view:=assessment_qti_read(b,t,job,0,50);perform assessment_qti_command(b,t,'qti-exhaustion-retry','retry',jsonb_build_object('id',job,'expected_revision',view->'revision','reason','Reviewed operational failure and authorized another processing attempt.'));
 if (select state from assessment_qti_jobs where id=job)<>'scan_queued' or (select attempts from assessment_qti_jobs where id=job)<>0 then raise exception 'Explicit operational recovery failed';end if;
 update tenant_memberships set status='active' where tenant_id=t and user_id=a;
end;$$;
rollback;
